    if(b.dataset.action==='plan-remove-concept'){const at=d.planning.concepts.findIndex(c=>c.id===b.dataset.id);if(at<0)return;const c=d.planning.concepts[at],affected=d.outputs.filter(o=>o.conceptId===c.id);state.removeConcept={id:c.id,draftId:d.id,brandId:d.brandId,revision:d.revision};openTask('Remove concept?',`<p>${h(c.name||'This concept')} will be removed. Its ${affected.length} deliverables will stay in the project as unassigned.</p><div class="actions">${button('Remove concept','plan-confirm-remove','secondary')}${button('Keep concept','close-task','primary')}</div>`,'inline');return;}
    if(b.dataset.action==='plan-confirm-remove'){const target=state.removeConcept;if(!target||target.draftId!==d.id||target.brandId!==d.brandId||target.revision!==d.revision)throw Error('This campaign changed. Reopen the concept before removing it.');d.planning.concepts=d.planning.concepts.filter(c=>c.id!==target.id);d.outputs.forEach(o=>{if(o.conceptId===target.id)o.conceptId='';});dirty();if(saveDraft()){closeTask();renderRoute();}return;}
    if(b.dataset.action==='plan-remove-output'){const at=d.outputs.findIndex(o=>o.id===b.dataset.id);if(at<0)return;const [removed]=d.outputs.splice(at,1),id=d.id;dirty();if(saveDraft()){renderRoute();toast('Deliverable removed.',()=>{if(state.draft?.id!==id)return toast('Reopen the campaign to restore it.');state.draft.outputs.splice(at,0,removed);dirty();if(saveDraft())renderRoute();});}return;}
