  let warmBrandTimer;
  function applyWorkspace(results,{keepOnFailure=false}={}){
    state.loading=false;
    if(results[0].status==='rejected'){
      if(keepOnFailure)toast('Could not refresh saved work. Showing your last loaded projects.');
      else{state.error=results[0].reason.message;state.projects=[];}
    }else{state.error='';state.projects=results[0].value.projects;}
    if(results[1].status==='fulfilled')state.products=results[1].value;
    if(results[2].status==='fulfilled')state.assets=results[2].value;
    state.libraryError=results[1].status==='rejected'||results[2].status==='rejected';
    if(state.libraryError)toast('Some library materials could not load. You can retry from the library.');
  }
