    if(el.dataset.output){const o=state.draft.outputs.find(o=>o.id===el.dataset.output),prop=el.dataset.prop;o[prop]=['width','height','slides','duration'].includes(prop)?Number(el.value):el.value;if(prop==='formatId'&&el.value!=='custom'){const f=M.formats.find(f=>f.id===el.value);o.width=f.w;o.height=f.h;}if([5,9].includes(o.featureId)&&['width','height','formatId'].includes(prop)&&o.staticParts)o.staticParts=o.staticParts.map(p=>({...p,width:o.width,height:o.height}));dirty();if(event.type==='change'&&prop==='slides'){const el=document.querySelector('[data-static-details="'+CSS.escape(o.id)+'"]');if(el){if(el.open)state.openStatic=o.id;el.outerHTML=staticSetup(o);}}if(event.type==='change'&&prop==='formatId'){saveDraft();renderRoute();}return;}
