    if(el.dataset.scene!==undefined){const p=state.project,item=projectItems(p)[state.outputIndex],scenes=sceneData(p,item),s=scenes[Number(el.dataset.scene)];if(el.dataset.prop==='duration'){const value=Number(el.value);if(!Number.isFinite(value)||value<1||value>120){el.setAttribute('aria-invalid','true');$('#sceneSave').textContent='Use a scene duration between 1 and 120 seconds.';return;}s.duration=value;}else s[el.dataset.prop]=el.value;el.removeAttribute('aria-invalid');const ok=saveProjectEdit(p);document.querySelectorAll('.timeline span').forEach((el,i)=>{el.textContent='Scene '+(i+1)+' · '+scenes[i].duration+'s';el.style.flex=scenes[i].duration;});$('#sceneSave').textContent=ok?scenes.reduce((a,s)=>a+s.duration,0)+' seconds planned · Saved on this device':'Could not save these changes.';return;}
