  document.addEventListener('click',event=>{const link=event.target.closest('a[href^="#"]');if(link&&state.brand){let target=link.getAttribute('href');if(target==='#create'){target='#create?from='+encodeURIComponent(state.hash||'home');link.href=target;}const r=M.navigation.parse(target);if(['project','brief','review'].includes(r.view)&&['home','projects','favourites','library'].includes(M.navigation.parse(state.hash).view)){rememberPage(target);brandNav().origins[r.parts[1]]=state.hash;saveNav();}else rememberPage();if(target==='#projects'&&brandNav().projects)link.href='#'+brandNav().projects;}const previewLink=event.target.closest('.journey-example a');if(state.demo&&previewLink&&previewLink.getAttribute('href')?.includes('preview-project')){event.preventDefault();demoNavigate('project-ready');return;}if(event.target.closest('[data-nav],.wordmark')){document.body.classList.remove('sidebar-mobile-open');syncSidebar();}if(event.target.closest('[data-search-link]'))closeTask();if(event.target.closest('.skip-link')){event.preventDefault();main.focus();main.scrollIntoView({block:'start'});return;}click(event);});
