  document.addEventListener('error',e=>{if(e.target.tagName==='IMG'){const img=e.target,wrap=img.parentElement;img.hidden=true;if(img.classList.contains('format-product-image')){wrap.classList.add('preview-unavailable');return;}if(img.classList.contains('brand-switch-logo')){const fallback=wrap.querySelector('.brand-switch-fallback');if(fallback)fallback.hidden=false;return;}if(wrap.classList.contains('project-cover'))wrap.classList.add('preview-unavailable');if(!wrap.querySelector('.asset-missing')){const n=document.createElement('span');n.className='hint asset-missing';n.textContent=wrap.classList.contains('art-frame')?'We couldn’t load this image. Your work is safe.':'Preview unavailable';wrap.append(n);if(wrap.classList.contains('art-frame'))wrap.insertAdjacentHTML('beforeend',button('Retry loading','retry-artwork','secondary'));}}},true);
