  async function start(){try{state.brands=(await D.brands()).filter(b=>['Duroflex','Sleepyhead'].includes(b.name)).sort((a,b)=>(a.name==='Duroflex'?-1:1));window.brandList=state.brands;if(!state.brands.length)throw Error('No brand workspaces are available. Ask your workspace administrator to restore them.');await loadBrand(new URLSearchParams(location.search).get('brand')||state.brands[0].id);}catch(e){state.loading=false;state.error=e.message;main.innerHTML=notice(clientError(e),'error',button('Retry','retry','text-button'));}}
